function libraryPage(container, title, body, cls="library-page") {
  container.innerHTML = `<section class="location ${cls}"><h1>${title}</h1><div class="library-body">${body}</div></section>`;
}
function libraryState(container, num) {
  const s = LIBRARY_STATES.find(x => x.RECORD === String(num));
  if (!s) { libraryPage(container,"Library","<p>Invalid state number.</p>"); return; }
  const facts = [
    ["building-i.gif","Capital",s.CAPITAL],["flower-i.gif","Flower",s.FLOWER],
    ["date-i.gif","Induction Date",s.ADMITTED],["bird-i.gif","Bird",s.BIRD],
    ["order-i.gif","Order of Induction",s.ORDER],["tree-i.gif","Tree",s.TREE],
    ["redball-i.gif","Nickname",s.NICKNAME],["music-i.gif","Song",s.SONG]
  ];
  const rows=[];
  for(let i=0;i<facts.length;i+=2) rows.push(`<tr><td><img src="graphics/library/${facts[i][0]}" alt="${facts[i][1]}"> <b>${facts[i][1]}:</b> ${facts[i][2]}</td><td><img src="graphics/library/${facts[i+1][0]}" alt="${facts[i+1][1]}"> <b>${facts[i+1][1]}:</b> ${facts[i+1][2]}</td></tr>`);
  const activity=s.activityRoute ? `<div class="library-activity"><a href="#library/${s.activityRoute}"><img src="graphics/library/school-i.gif" alt="Children" width="70" height="70"><br>Click here to play a game!</a></div>` : "";
  const region=s.LOCATION ? `<a href="#library/${s.RETURN}">Return to ${s.LOCATION} states map</a>` : "";
  const heading=s.RECORD==="51" ? "Here are some interesting facts about the Capital of the United States:" : `Here are some interesting facts about ${s.NAME}`;
  container.innerHTML=`<section class="location library-page"><div class="library-state-head"><img src="graphics/library/${s.MAP}" alt="${s.NAME} map"><h1>${s.NAME.toUpperCase()}</h1><img src="graphics/library/${s.FLAG}" alt="US Flag" class="state-flag"></div><h2>${heading}</h2><table class="state-facts">${rows.join("")}</table>${activity}<p><a href="#library/6000">Return to USA map</a>${region ? " &nbsp; | &nbsp; "+region : ""}</p></section>`;
}
function libraryTale(container, kind, answer=false) {
  const t=LIBRARY_TALES[kind];
  if(!t) return;
  const storage="kt_library_tale_"+kind;
  let vals={};
  try { vals=JSON.parse(sessionStorage.getItem(storage)||"{}"); } catch(e){}
  if(!answer) {
    const fields=t.fields.map(f=>{
      if(f[0]==="name") return `<p>${f[1]} <input name="${f[0]}" required maxlength="30"></p>`;
      return `<p>${f[1]} <select name="${f[0]}">${f[2].map(v=>`<option>${v}</option>`).join("")}</select></p>`;
    }).join("");
    container.innerHTML=`<section class="location library-game"><h1>${t.title}</h1><img src="graphics/library/${t.image}" alt="${t.title}"><hr><p>The following are brief paragraphs that will tell you a little more about the choices you made. Read through them and try to imagine how the sentences would have sounded with the other selections.</p><form id="tale-form">${fields}<button>Present Tale!</button></form><p><a href="#library/state/${kind==="wi"?49:kind==="or"?37:7}">Back to ${t.state}</a></p></section>`;
    container.querySelector("#tale-form").addEventListener("submit",e=>{
      e.preventDefault(); const fd=new FormData(e.target); vals=Object.fromEntries(fd.entries());
      try{sessionStorage.setItem(storage,JSON.stringify(vals));}catch(err){} window.location.hash="#library/game/"+kind+"-tale/answer";
    });
    return;
  }
  const name=vals.name||"children";
  let body="";
  if(kind==="wi") body=`<p>When <b>${name}</b> and other children visit Wisconsin, they can learn all about the glaciers that once covered most of the state. Because of the glaciers, most of Wisconsin is flat and has very fertile soil. Many crops like <b>${vals.favorite||"peas"}</b>, corn, and cranberries are grown on these lands today. But Wisconsin is most famous for its dairy farming. Wisconsin produces more milk and dairy products than any other state.</p><hr><p>The very first people to live in Wisconsin were the Native Indians. Tribes like the <b>${vals.native||"Winnebago"}</b>, Fox, Sauk, and Kickapoo settled in Wisconsin after the Ice Age. Some Native Americans built large burial mounds shaped like animals. When Europeans first came to Wisconsin, they were friends with the Native people. They traded furs and other goods with them. Through wars and diseases many Native people have died. Today, most Native Americans live on reservations.</p><hr><p>Many famous individuals were born in Wisconsin. One name that <b>${name}</b> might be familiar with is Oshkosh. Oshkosh was a famous Menominee Indian leader who successfully kept his tribal lands. There is a city named after him, Oshkosh. <b>${name}</b> might have read some books, or seen a television show about another famous Wisconsinite, Laura Ingalls Wilder, who was born in Pepin, Wisconsin. She wrote the <i>Little House on the Prairie</i> books.</p>`;
  if(kind==="or") body=`<p>Oregon is bordered on three sides by Washington, Idaho, Nevada and California. The very <b>${vals.trees||"cute"}</b> Pacific Ocean borders Oregon on the west side of the state. The Columbia River is 7 miles wide where it empties into the Pacific Ocean. It is so <b>${vals.trees||"cute"}</b>, in fact, that <b>${vals.trees||"cute"}</b> oceangoing ships can travel up the river for 200 miles. The <b>${vals.trees||"cute"}</b> Crater Lake is the deepest lake in the United States.</p><hr><p>In 1971 Oregon became the first state to require that beverage cans and bottles be returnable. Now all of Oregon's <b>${vals.recycle||"adults"}</b> participate in the recycling program.</p><hr><p>In a process called clear-cutting, many of Oregon's <b>${vals.forest||"new"}</b> forests have disappeared. Many <b>${vals.forest||"new"}</b> trees were between 200 and 1,200 years old. Many animals and birds are endangered by the removal of these trees. Oregon is now requiring smarter ways to remove trees. In the future Oregon hopes to have many <b>${vals.forest||"new"}</b> forests again.</p>`;
  if(kind==="ct") body=`<p><b>${vals.tribes||"Many"}</b> Native Indian tribes such as the Niantic, Podunk, Qunnipiac, and Pequot are native to the area of Connecticut. As in most regions of our country, Native Americans were killed to provide land and resources for the European settlers. <b>${vals.tribes||"Many"}</b> Indians were killed by the diseases they caught from the Europeans. Today, the remaining tribes live on reservations.</p><hr><p>Connecticut is so <b>${vals.animals||"small"}</b> that it could fit within Alaska more than 117 times. Even though Connecticut is a <b>${vals.animals||"small"}</b> state compared to other states, it has a large population. With so many people living in such a <b>${vals.animals||"small"}</b> area most large animals have been pushed out of the state. Many <b>${vals.animals||"small"}</b> animals still live in Connecticut.</p><hr><p>In the 1800s Connecticut had a <b>${vals.pollution||"problem"}</b>. There was a shortage of fertile land and an abundance of water. Connecticut became a very industrialized state with textile mills and factories. All of these industries dumped pollutants into the waters of Connecticut. This caused a new <b>${vals.pollution||"problem"}</b> of water pollution. To help solve the <b>${vals.pollution||"problem"}</b>, Connecticut has written laws concerning what can be put into its rivers.</p>`;
  container.innerHTML=`<section class="location library-game"><h1>${t.title}</h1><img src="graphics/library/${t.image}" alt="${t.state}"><hr><p>Here is the tale based on your choices:</p><div class="tale-answer">${body}</div><p><a href="#library/game/${kind}-tale">Try different choices</a> &nbsp; <a href="#library/state/${kind==="wi"?49:kind==="or"?37:7}">Back to ${t.state}</a></p></section>`;
}
function libraryFillin(container, kind, answer=false) {
  const rec=LIBRARY_FILLINS[kind==="ny"?"1":"2"];
  if(!answer) {
    const qs=[1,2,3,4,5].map(i=>({q:rec["QUESTION"+i]||"",options:[]})); // questions are supplied below
    const options=kind==="ny"?[
      ["Sears Tower","Leaning Tower of Pisa","Empire State Building","World Trade Center Buildings"],
      ["Madison Square Garden","Sun Devil Stadium","Coors Field","Riverside Stadium"],
      ["Alonso Alvarez de Pineda","Giovanni da Verrazano","Maros de Niza","Juan de Gaeten"],
      ["Pequot","Apache","Sioux","Manhattan"],["One out of every 2","75","About 20 million","Billions!!!"]
    ]:[
      ["Donkeys and Cows","District of Columbia","Donuts and Coffee"],["Clara Barton","Susan B. Anthony","Julia Ward Howe"],
      ["George Washington","Theodore Roosevelt","Pierre L' Enfant"],["Capital","Capitol","Capitalize"],["23 years","5 years","18 months"]
    ];
    const questions=kind==="ny"?["What is the tallest skyscraper in New York?","What is the name of the famous sports center in New York?","In 1524 New York was discovered by?","The Dutch bought New Amsterdam (Manhattan) from what Native American tribe?","How many Americans can trace their roots to someone who passed through Ellis Island?"]:["What do the initials D.C. stand for?","What famous woman founded The Red Cross?","What famous U.S. President never lived in the White House?","Which term below is used for Washington D.C.?","How long on average does a $1 bill last?"];
    container.innerHTML=`<section class="location library-game"><h1>${rec.HEADING}</h1><p>Select an answer for each question, then choose <b>Learn More!</b></p><form id="fill-form">${questions.map((q,i)=>`<fieldset><legend>${q}</legend>${options[i].map(v=>`<label><input type="radio" name="q${i+1}" value="${v.replace(/"/g,"&quot;")}" required> ${v}</label><br>`).join("")}</fieldset>`).join("")}<button>Learn More!</button></form><p><a href="#library/state/${kind==="ny"?36:51}">Back to state</a></p></section>`;
    container.querySelector("#fill-form").addEventListener("submit",e=>{e.preventDefault();const fd=new FormData(e.target);try{sessionStorage.setItem("kt_fill_"+kind,JSON.stringify(Object.fromEntries(fd.entries())))}catch(err){}window.location.hash="#library/game/"+kind+"-fillin/answer";});
    return;
  }
  let vals={};try{vals=JSON.parse(sessionStorage.getItem("kt_fill_"+kind)||"{}")}catch(e){}
  const sol=[1,2,3,4,5].map(i=>rec["SOL"+i]);
  const paras=[1,2,3,4,5].map(i=>({p:rec["PARAGRAPH"+i],a:[rec[`ITEM${i}A`],rec[`ITEM${i}B`],rec[`ITEM${i}C`]].filter(Boolean)}));
  const content=paras.map((x,i)=>`<div class="fill-answer"><h3>Question ${i+1}: ${vals["q"+(i+1)]===sol[i]?"Correct!":"Not quite."}</h3><p>${x.p}</p>${x.a.map(a=>`<p>${a}</p>`).join("")}</div>`).join("");
  container.innerHTML=`<section class="location library-game"><h1>${rec.HEADING}</h1>${content}<p><a href="#library/game/${kind}-fillin">Try again</a></p></section>`;
}
function libraryWordSearch(container, kind, answer=false) {
  const data=LIBRARY_WORDSEARCH[kind]; if(!data)return;
  let body=answer?data.answer:data.page;
  if(answer) body=body.replace(/#library\/game\/[^"]+/g, "#library/game/"+kind+"-wordsearch");
  container.innerHTML=`<section class="location library-page library-game"><div class="library-body">${body}</div></section>`;
}
KidsTown.locations["library"] = {
  render(container, subRoute) {
    if(!subRoute) { libraryPage(container,"KidsTown Library",LIBRARY_MAIN); return; }
    if(/^state\/\d+$/.test(subRoute)) { libraryState(container,subRoute.split("/")[1]); return; }
    if(LIBRARY_REGION_PAGES[subRoute]) { libraryPage(container,"KidsTown Library",LIBRARY_REGION_PAGES[subRoute]); return; }
    if(subRoute.startsWith("game/")) {
      const p=subRoute.split("/");
      const g=p[1], answer=p[2]==="answer";
      if(g==="ak-wordsearch"||g==="az-wordsearch"||g==="ne-wordsearch"){libraryWordSearch(container,g.slice(0,2),answer);return;}
      if(g==="wi-tale"||g==="or-tale"||g==="ct-tale"){libraryTale(container,g.slice(0,2),answer);return;}
      if(g==="ny-fillin"||g==="dc-fillin"){libraryFillin(container,g.slice(0,2),answer);return;}
    }
    // numeric original keys
    if(LIBRARY_REGION_PAGES[subRoute]) { libraryPage(container,"KidsTown Library",LIBRARY_REGION_PAGES[subRoute]); return; }
    libraryPage(container,"KidsTown Library","<p><a href=\"#library\">Return to the Library.</a></p>");
  }
};
